window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76be091f06177fc6"]={"versions": [{"id": "FIG-76be091f06177fc6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-2.0-Komponentendiagramm / BSW-Schnittstellenarchitektur (<code>AUTOSAR BSW Module Interface Diagram</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation aller statischen Schnittstellenbeziehungen des BSW-Moduls <code>DoIP</code> (Diagnostic over IP, AUTOSAR Classic R20-11, SWS Chapter 5) zu Nachbarmodulen des Communication- und Diagnostic-Stacks sowie zum BSW-Scheduler und applikativen Callouts.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li><strong>Nach oben (Diagnose-Applikationsebene):</strong> Anbindung an den Diagnostic Communication Manager (<code>Dcm</code>) bzw. <code>PduR</code> über standardisierte ComStack-Transportprotokoll-Schnittstellen (TP).</li>\n<li><strong>Nach unten (Ethernet-Transportebene):</strong> Anbindung an den Socket Adaptor (<code>SoAd</code>) über Communication Interface (IF für UDP) und Transport Protocol (TP für TCP).</li>\n<li><strong>System- und Querschnittsfunktionen:</strong> Systemsteuerungs-Hooks (<code>BswM</code>/<code>EcuM</code> via Activation Line und Vehicle Announcement Trigger), Diagnosefehler-Tracing (<code>Det</code>) sowie fahrzeugspezifische Konfigurations-Callouts (<code>&lt;User&gt;_*</code>) gemäß ISO 13400-2.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale Entität</p>\n<ul class=\"fig-list\">\n<li><code>«module» DoIP</code>: Ausführendes BSW-Kernmodul des AUTOSAR Classic Communication Stacks.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen und Modellierungssemantik</p>\n<ul class=\"fig-list\">\n<li><code>«realize»</code>: Vom <code>DoIP</code>-Modul implementierte und exportierte Funktionen/Schnittstellen (Provided Interfaces).</li>\n<li><code>«mandatory»</code>: Vom <code>DoIP</code>-Modul zwingend benötigte Aufrufschnittstellen externer BSW-Module (Required Interfaces).</li>\n<li><code>«optional»</code>: Konfigurierbare bzw. bedingt kompilierte Abhängigkeiten (z. B. DET-Reporting, <code>TxConfirmation</code>).</li>\n<li><code>«configurable»</code>: Projektspezifische Anwender-Callbacks (Callouts), die durch OEM-/Integratorcode bereitgestellt werden.</li>\n<li><code>«generic_interface»</code>: Standardisierte AUTOSAR ComStack-Primitiven (IF/TP), die mehrfach instanziiert und PDU-spezifisch geroutet werden.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenübersicht nach Kommunikationspartnern</p>\n<ol class=\"fig-list\">\n<li><strong>Modul- und Scheduler-Verwaltung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Types</code>: Exportierte Header- und Datentypdefinitionen (z. B. PduId-Zuordnungen, Verbindungszustände).</li>\n<li><code>DoIP_Init</code>: Modulinitialisierung durch <code>EcuM</code> / <code>BswM</code>.</li>\n<li><code>DoIP_GetVersionInfo</code>: Auslesen der AUTOSAR-Versionsinformationen.</li>\n<li><code>DoIP_MainFunction</code>: Zyklische BSW-Scheduler-Task für Protokoll-Timer (Inactivity Timer, Alive Check), Session-Monitoring und State-Machine-Updates.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum Socket Adaptor (<code>SoAd</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Required (<code>«mandatory»</code> DoIP $\\rightarrow$ SoAd):</strong></li>\n<li><code>SoAd_SoConCtrl</code>: Öffnen, Schließen und Modus-Umschaltung von Socket-Verbindungen.</li>\n<li><code>SoAd_Info</code>: Abfrage dynamischer Socket-Parameter (z. B. IP-Adressen, Ports).</li>\n<li><code>SoAd_GeneralCtrl</code>: Übergeordnete Socket-Adapter-Steuerung.</li>\n<li><code>SoAd_SetRemoteAddr</code> / <code>SoAd_SetUniqueRemoteAddr</code>: Dynamische Zuweisung von Remote-IP/Port für eingehende/ausgehende Client-Sockets.</li>\n<li><code>SoAd_ReadDhcpHostNameOption</code> / <code>SoAd_WriteDhcpHostNameOption</code>: Handhabung der DHCP-Option 12 (Host Name) zur Fahrzeugerkennung.</li>\n<li><code>«generic_interface» Transmit</code> (<code>+SoAd</code>): Senden von DoIP-PDUs via SoAd (sowohl IF für UDP-Broadcasts/-Unicasts als auch TP für TCP-Streams).</li>\n<li><strong>Provided / Callbacks (<code>«realize»</code> SoAd $\\rightarrow$ DoIP):</strong></li>\n<li><code>DoIP_SoConModeChg</code>: Benachrichtigung über Zustandswechsel einer Socket-Connection (<code>SOAD_SOCON_ONLINE</code>, <code>SOAD_SOCON_OFFLINE</code>).</li>\n<li><code>DoIP_LocalIpAddrAssignmentChg</code>: Benachrichtigung über Bezug oder Verlust einer lokalen IP-Adresse (Trigger für Vehicle Announcement).</li>\n<li><code>«generic_interface» RxIndication</code> / <code>TxConfirmation</code>: Statusrückmeldungen für UDP-basierte IF-Nachrichten.</li>\n<li><code>«generic_interface» StartOfReception</code>, <code>CopyRxData</code>, <code>TpRxIndication</code>: Empfangspfad für TCP-basierte DoIP-Nutzlasten via SoAd-TP.</li>\n<li><code>«generic_interface» CopyTxData</code>, <code>TpTxConfirmation</code>: Sendepfad für TCP-basierte DoIP-Antworten via SoAd-TP.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum Diagnostic Communication Manager (<code>Dcm</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Provided für Dcm (<code>«realize»</code> Dcm $\\rightarrow$ DoIP):</strong></li>\n<li><code>«generic_interface» Transmit</code>: Dcm fordert das Senden einer Diagnoseantwort an (<code>DoIP_TpTransmit</code>).</li>\n<li><code>«generic_interface» CancelTransmit</code>: Vorzeitiger Abbruch einer laufenden Diagnose-Antwortübertragung.</li>\n<li><code>DoIP_TpCancelTransmit</code> / <code>DoIP_TpCancelReceive</code>: AUTOSAR-konforme TP-spezifische Abbruchfunktionen.</li>\n<li><strong>Required von Dcm (<code>«mandatory»</code> DoIP $\\rightarrow$ Dcm):</strong></li>\n<li><code>Dcm_GetVin</code>: Synchrones Auslesen der 17-stelligen Fahrzeug-Identifikationsnummer (VIN) für DoIP-Vehicle-Identification-/Announcement-Messages.</li>\n<li><code>«generic_interface» StartOfReception</code>, <code>CopyRxData</code>, <code>TpRxIndication</code>: Weiterleitung der extrahierten UDS-Diagnoseanfrage an den Dcm.</li>\n<li><code>«generic_interface» CopyTxData</code>, <code>TpTxConfirmation</code>: Abruf der UDS-Antwortbytes aus dem Dcm-Puffer und Übertragungsbestätigung.</li>\n<li><code>«generic_interface» TxConfirmation</code> (<code>«optional»</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Trigger & Hardware-Aktivierung (<code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_ActivationLineSwitch</code>: Hardware-Flankensignal (z. B. von <code>BswM</code> oder CDD via Pin gemessen) zur Aktivierung/Deaktivierung des DoIP-Stacks (ISO 13400-2 Activation Line).</li>\n<li><code>DoIP_TriggerVehicleAnnouncement</code>: Manueller/systemischer Trigger zur Aussendung von Vehicle Announcement PDUs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung (Required / <code>«optional»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError</code>: Weiterleitung von Parametrier- und API-Fehlern an den Development Error Tracer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Herstellerspezifische Anwender-Callouts (<code>«configurable»</code> User $\\rightarrow$ DoIP):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>&lt;User&gt;_DoIPGetGidCallback</code>: Abruf der Group Identification (GID) für Fahrzeugflotten-Identifikation.</li>\n<li><code>&lt;User&gt;_DoIPTriggerGidSyncCallback</code>: Trigger zur GID-Synchronisation bei Multi-ECU-Architekturen.</li>\n<li><code>&lt;User&gt;_DoIPGetPowerModeCallback</code>: Abfrage des Fahrzeug-/ECU-Energiemodus (Diagnosebereitschaft).</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationAuthentication</code>: OEM-spezifische Authentifizierung vor Aktivierung eines Routing-Kanals.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationConfirmation</code>: Bestätigungsroutine für die Routing-Aktivierung.</li>\n<li><code>&lt;User&gt;_DoIPGetFurtherActionByteCallback</code>: Dynamische Bereitstellung des OEM-spezifischen Statusbytes im Routing-Activation-Response.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stack-Hochlauf und Discovery-Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Init()</code> wird durch <code>EcuM</code>/<code>BswM</code> synchron aufgerufen.</li>\n<li>Das Aktivierungssignal trifft ein (<code>DoIP_ActivationLineSwitch()</code>), gefolgt von <code>DoIP_LocalIpAddrAssignmentChg()</code> nach erfolgreichem DHCP-/Link-Local-Adressbezug.</li>\n<li>Das Modul ruft synchron <code>Dcm_GetVin()</code> und <code>&lt;User&gt;_DoIPGetGidCallback()</code> ab.</li>\n<li>Nach Ablauf des Initial Inactivity Timers sendet <code>DoIP</code> über <code>SoAd_IfTransmit()</code> (<code>Transmit</code> <code>+SoAd</code>) bis zu dreimal die UDP-Vehicle-Announcement-Nachricht (bestätigt via <code>TxConfirmation</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TCP-Verbindungsaufbau und Routing-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tester öffnet TCP-Port 13400; SoAd signalisiert <code>DoIP_SoConModeChg()</code>.</li>\n<li>Tester sendet Routing Activation Request via TCP; SoAd leitet Daten über <code>StartOfReception()</code> $\\rightarrow$ <code>CopyRxData()</code> $\\rightarrow$ <code>TpRxIndication()</code> an <code>DoIP</code>.</li>\n<li><code>DoIP</code> verarbeitet den Header und ruft synchron die Callouts <code>&lt;User&gt;_DoIPRoutingActivationAuthentication()</code> und <code>&lt;User&gt;_DoIPRoutingActivationConfirmation()</code> auf.</li>\n<li>Bei Erfolg wird der Routing-Kanal geöffnet, und <code>DoIP</code> sendet die Bestätigung via SoAd-TP an den Tester zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>UDS-Diagnosedatentransfer (Gateway-Mechanismus DoIP $\\leftrightarrow$ Dcm):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rx-Pfad (Tester $\\rightarrow$ Dcm):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>SoAd ruft <code>DoIP_StartOfReception()</code>, streamt Segmente über <code>DoIP_CopyRxData()</code> und beendet via <code>DoIP_TpRxIndication()</code>.</li>\n<li><code>DoIP</code> decodiert den DoIP-Header (Payload Type <code>0x8001</code>), prüft die logische Zieladresse und initiiert die Weiterleitung an den Dcm via <code>Dcm_StartOfReception()</code>.</li>\n<li>Daten werden per <code>Dcm_CopyRxData()</code> direkt an den Dcm übergeben und mit <code>Dcm_TpRxIndication()</code> abgeschlossen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Tx-Pfad (Dcm $\\rightarrow$ Tester):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Dcm initiiert Antwort über <code>DoIP_TpTransmit()</code>.</li>\n<li><code>DoIP</code> fordert Übertragung bei SoAd an (<code>SoAd_TpTransmit()</code>).</li>\n<li>SoAd holt den DoIP-Header und Payload via <code>DoIP_CopyTxData()</code> ab; <code>DoIP</code> ruft parallel <code>Dcm_CopyTxData()</code> auf, um die Nutzlast aus dem Dcm-Puffer zu multiplexen.</li>\n<li>Abschluss über <code>DoIP_TpTxConfirmation()</code> $\\rightarrow$ <code>Dcm_TpTxConfirmation()</code>.</li>\n</ol>\n<ol class=\"fig-list\">\n<li><strong>Timeouts, Abbruch und Exception Handling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_MainFunction()</code> prüft zyklisch den <em>General Inactivity Timer</em> und <em>Alive Check Timer</em>. Bei Timeout wird <code>SoAd_SoConCtrl()</code> aufgerufen, um den Socket zu trennen.</li>\n<li>Bricht der Dcm einen Transfer ab (<code>DoIP_TpCancelTransmit()</code> / <code>DoIP_TpCancelReceive()</code>), schließt <code>DoIP</code> die TP-Transaktion und setzt Puffer/Zustände zurück.</li>\n<li>Ungültige Header oder unzulässige PDU-Größen führen zum synchronen Aufruf von <code>Det_ReportError()</code> (falls <code>DoIPDevErrorDetect == TRUE</code>) und Rückgabe von DoIP-NACKs an den Client.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Routing- und ComStack-Konfiguration:</strong></li>\n<li>Im System-Description-/BSW-Konfigurator (<code>ARXML</code>) müssen strikt zwei disjunkte PDU-Kategorien getrennt werden:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IF-PDUs</strong> für unbestätigte/broadcast UDP-Kommunikation (<code>SoAd_IfTransmit</code>, <code>RxIndication</code>, <code>TxConfirmation</code>).</li>\n<li><strong>TP-PDUs</strong> für segmentierte, session-gebundene TCP-Kommunikation (<code>StartOfReception</code>, <code>CopyRxData</code>, <code>CopyTxData</code>, etc.).</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die symbolischen PDU-IDs zwischen <code>DoIP</code>, <code>SoAd</code> und <code>Dcm</code> müssen konsistent zugeordnet sein; Fehlkonfigurationen führen zu Routing-Deadlocks im TP-Puffer.</li>\n<li><strong>Reentrancy- und Concurrency-Restriktionen:</strong></li>\n<li>Die Callbacks <code>CopyTxData()</code> und <code>CopyRxData()</code> laufen typischerweise im Interrupt- oder High-Priority-Task-Kontext des Ethernet-Treiber-/TCPIP-Stacks.</li>\n<li>Zugriff auf gemeinsame Puffer zwischen <code>Dcm</code> und <code>DoIP</code> muss zwingend über kritische Abschnitte (<code>SchM_Enter_DoIP_<em>()</code>, <code>SchM_Exit_DoIP_</em>()</code>) gegen Concurrent Access abgesichert werden.</li>\n<li><strong>Callout-Ausführungszeit (Hard Deadlines):</strong></li>\n<li>Die <code>&lt;User&gt;_*</code>-Schnittstellen (insbesondere Authentifizierung und Bestätigung) müssen strikt non-blocking und bounded-time implementiert sein. Eine Verzögerung blockiert die TCP-Zustandsmaschine und führt zum Ablauf des ISO-13400-Initial-Inactivity-Timers (typisch 2000 ms) auf Testerseite.</li>\n<li><strong>Normative ISO-13400-2 Abhängigkeiten:</strong></li>\n<li><code>Dcm_GetVin()</code> muss thread-sicher bereitstehen, sobald <code>DoIP_Init()</code> durchlaufen ist, da Vehicle Announcements unmittelbar nach IP-Vergabe automatisiert abgesetzt werden.</li>\n</ul>"}, {"id": "FIG-21343f4f1ef8c8c1", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-2.0-Komponentendiagramm / BSW-Schnittstellenarchitektur (<code>AUTOSAR BSW Module Interface Diagram</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation aller statischen Schnittstellenbeziehungen des BSW-Moduls <code>DoIP</code> (Diagnostic over IP, AUTOSAR Classic R21-11/R22-11, SWS Chapter 5) zu Nachbarmodulen des Communication- und Diagnostic-Stacks sowie zum BSW-Scheduler.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li><strong>Nach oben (Diagnose-Routing- und Applikationsebene):</strong> Anbindung an den PDU Router (<code>PduR</code>) über konkrete transport- und interfacerelevante ComStack-Schnittstellen sowie an den Diagnostic Communication Manager (<code>Dcm</code>) zur synchronen VIN-Abfrage.</li>\n<li><strong>Nach unten (Ethernet-Transportebene):</strong> Anbindung an den Socket Adaptor (<code>SoAd</code>) über Communication Interface (IF für UDP) und Transport Protocol (TP für TCP) sowie spezifische Socket- und IP-Adressverwaltungs-APIs.</li>\n<li><strong>System- und Querschnittsfunktionen:</strong> Systemsteuerungs-Hooks (<code>BswM</code>/<code>EcuM</code> via Activation Line und Vehicle Announcement Trigger) sowie Diagnosefehler-Tracing (<code>Det</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale Entität</p>\n<ul class=\"fig-list\">\n<li><code>«module» DoIP</code>: Ausführendes BSW-Kernmodul des AUTOSAR Classic Communication Stacks.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen und Modellierungssemantik</p>\n<ul class=\"fig-list\">\n<li><code>«realize»</code>: Vom <code>DoIP</code>-Modul implementierte und exportierte Funktionen/Schnittstellen (Provided Interfaces, auf der linken Seite angeordnet).</li>\n<li><code>«mandatory»</code>: Vom <code>DoIP</code>-Modul zwingend benötigte Aufrufschnittstellen externer BSW-Module (Required Interfaces, auf der rechten Seite angeordnet).</li>\n<li><code>«optional»</code>: Konfigurierbare bzw. bedingt kompilierte Abhängigkeiten (<code>Det_ReportError</code>, <code>PduR_DoIPIfTxConfirmation</code>).</li>\n<li><code>«derived_generic_interface»</code>: Konkret abgeleitete Instanzen standardisierter AUTOSAR ComStack-Primitiven (IF/TP) mit modulspezifischem Namenspräfix für Sender und Empfänger.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenübersicht nach Kommunikationspartnern</p>\n<ol class=\"fig-list\">\n<li><strong>Modul- und Scheduler-Verwaltung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Types</code>: Exportierte Header- und Datentypdefinitionen (z. B. PduId-Zuordnungen, Verbindungszustände).</li>\n<li><code>DoIP_Init</code>: Modulinitialisierung durch <code>EcuM</code> / <code>BswM</code>.</li>\n<li><code>DoIP_GetVersionInfo</code>: Auslesen der AUTOSAR-Versionsinformationen.</li>\n<li><code>DoIP_MainFunction</code>: Zyklische BSW-Scheduler-Task für Protokoll-Timer, Session-Monitoring und State-Machine-Updates.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Trigger & Hardware-Aktivierung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_ActivationLineSwitch</code>: Hardware-Flankensignal zur Aktivierung/Deaktivierung des DoIP-Stacks (ISO 13400-2 Activation Line).</li>\n<li><code>DoIP_TriggerVehicleAnnouncement</code>: Manueller/systemischer Trigger zur Aussendung von Vehicle Announcement PDUs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum Socket Adaptor (<code>SoAd</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Required (<code>«mandatory»</code> DoIP $\\rightarrow$ SoAd):</strong></li>\n<li><code>SoAd_GetSoConId</code>: Ermittlung des Socket-Connection-Bezeichners.</li>\n<li><code>SoAd_OpenSoCon</code>: Explizites Öffnen einer Socket-Verbindung.</li>\n<li><code>SoAd_CloseSoCon</code>: Explizites Schließen einer Socket-Verbindung.</li>\n<li><code>SoAd_GetPhysAddr</code>: Abfrage der physikalischen MAC-Adresse für eine Socket-Verbindung.</li>\n<li><code>SoAd_RequestIpAddrAssignment</code> / <code>SoAd_ReleaseIpAddrAssignment</code>: Anforderung und Freigabe lokaler IP-Adresszuweisungen.</li>\n<li><code>SoAd_ReadDhcpHostNameOption</code> / <code>SoAd_WriteDhcpHostNameOption</code>: Handhabung der DHCP-Option 12 (Host Name) zur Fahrzeugerkennung.</li>\n<li><code>«derived_generic_interface» SoAd_IfTransmit</code>: Senden unbestätigter bzw. UDP-basierter DoIP-Nachrichten.</li>\n<li><code>«derived_generic_interface» SoAd_TpTransmit</code>: Initiierung segmentierter TCP-Übertragungen via SoAd-TP.</li>\n<li><strong>Provided / Callbacks (<code>«realize»</code> SoAd $\\rightarrow$ DoIP):</strong></li>\n<li><code>DoIP_SoConModeChg</code>: Benachrichtigung über Zustandswechsel einer Socket-Connection.</li>\n<li><code>DoIP_LocalIpAddrAssignmentChg</code>: Benachrichtigung über Bezug oder Verlust einer lokalen IP-Adresse.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdIfTxConfirmation</code> / <code>DoIP_SoAdIfRxIndication</code>: Statusmeldungen für UDP-basierte Schnittstellenkommunikation.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpStartOfReception</code>, <code>DoIP_SoAdTpCopyRxData</code>, <code>DoIP_SoAdTpRxIndication</code>: Empfangspfad für TCP-basierte DoIP-Nutzlasten via SoAd-TP.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpCopyTxData</code>, <code>DoIP_SoAdTpTxConfirmation</code>: Sendepfad für TCP-basierte DoIP-Antworten via SoAd-TP.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum PDU Router (<code>PduR</code>) & Diagnostic Communication Manager (<code>Dcm</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Provided für PduR (<code>«realize»</code> PduR $\\rightarrow$ DoIP):</strong></li>\n<li><code>«derived_generic_interface» DoIP_TpTransmit</code>: Anforderung des PduR zur Übertragung diagnostischer Transportnachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfTransmit</code>: Anforderung des PduR zur Übertragung unbestätigter Diagnosenachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfCancelTransmit</code>: Abbruch einer laufenden IF-Übertragung.</li>\n<li><code>DoIP_TpCancelTransmit</code> / <code>DoIP_TpCancelReceive</code>: Abbruch laufender TP-Sende- bzw. Empfangsvorgänge.</li>\n<li><strong>Required von PduR / Dcm (<code>«mandatory»</code> / <code>«optional»</code> DoIP $\\rightarrow$ PduR/Dcm):</strong></li>\n<li><code>Dcm_GetVin</code> (<code>«mandatory»</code>): Synchrones Auslesen der 17-stelligen Fahrzeug-Identifikationsnummer (VIN).</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpStartOfReception</code>, <code>PduR_DoIPTpCopyRxData</code>, <code>PduR_DoIPTpRxIndication</code> (<code>«mandatory»</code>): Weiterleitung empfangener diagnostischer TP-Nutzdaten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpCopyTxData</code>, <code>PduR_DoIPTpTxConfirmation</code> (<code>«mandatory»</code>): Datenabruf und Bestätigung ausgehender TP-Diagnosenachrichten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPIfTxConfirmation</code> (<code>«optional»</code>): Optionale Sende-Bestätigung für IF-Nachrichten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung (Required / <code>«optional»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError</code>: Weiterleitung von Fehlern an den Development Error Tracer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stack-Hochlauf und Discovery-Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Init()</code> wird durch <code>EcuM</code>/<code>BswM</code> synchron aufgerufen.</li>\n<li>Das Aktivierungssignal trifft ein (<code>DoIP_ActivationLineSwitch()</code>), gefolgt von der Adressanforderung (<code>SoAd_RequestIpAddrAssignment()</code>) und Rückmeldung über Adressbezug via <code>DoIP_LocalIpAddrAssignmentChg()</code>.</li>\n<li>Das Modul ruft synchron <code>Dcm_GetVin()</code> ab.</li>\n<li>Nach Ablauf des Initial Inactivity Timers sendet <code>DoIP</code> über <code>SoAd_IfTransmit()</code> bis zu dreimal die UDP-Vehicle-Announcement-Nachricht (bestätigt via <code>DoIP_SoAdIfTxConfirmation()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TCP-Verbindungsaufbau und Socket-Steuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tester öffnet TCP-Port 13400; SoAd signalisiert den Zustandswechsel über <code>DoIP_SoConModeChg()</code>.</li>\n<li>Zur Steuerung und Identifikation der Sockets verwendet DoIP <code>SoAd_GetSoConId()</code>, <code>SoAd_OpenSoCon()</code> und <code>SoAd_CloseSoCon()</code>.</li>\n<li>Tester sendet Routing Activation Request via TCP; SoAd leitet Daten über <code>DoIP_SoAdTpStartOfReception()</code> $\\rightarrow$ <code>DoIP_SoAdTpCopyRxData()</code> $\\rightarrow$ <code>DoIP_SoAdTpRxIndication()</code> an <code>DoIP</code>.</li>\n<li>Nach interner Auswertung und Aktivierung des Routings sendet <code>DoIP</code> die Bestätigung via <code>SoAd_TpTransmit()</code> und <code>DoIP_SoAdTpCopyTxData()</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>UDS-Diagnosedatentransfer (Gateway-Mechanismus DoIP $\\leftrightarrow$ PduR):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rx-Pfad (Tester $\\rightarrow$ PduR):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>SoAd meldet eingehende Segmente über <code>DoIP_SoAdTpStartOfReception()</code>, streamt via <code>DoIP_SoAdTpCopyRxData()</code> und schließt per <code>DoIP_SoAdTpRxIndication()</code> ab.</li>\n<li><code>DoIP</code> decodiert den DoIP-Header, ermittelt die logische Zieladresse und initiiert die Weiterleitung an den PduR über <code>PduR_DoIPTpStartOfReception()</code>.</li>\n<li>Daten werden per <code>PduR_DoIPTpCopyRxData()</code> direkt an den PduR übergeben und mit <code>PduR_DoIPTpRxIndication()</code> abgeschlossen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Tx-Pfad (PduR $\\rightarrow$ Tester):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR initiiert Antwort über <code>DoIP_TpTransmit()</code>.</li>\n<li><code>DoIP</code> fordert Übertragung bei SoAd an (<code>SoAd_TpTransmit()</code>).</li>\n<li>SoAd holt Header und Payload über <code>DoIP_SoAdTpCopyTxData()</code> ab; <code>DoIP</code> ruft parallel <code>PduR_DoIPTpCopyTxData()</code> auf, um Diagnosedaten aus dem PduR-Puffer abzurufen.</li>\n<li>Abschluss über <code>DoIP_SoAdTpTxConfirmation()</code> $\\rightarrow$ <code>PduR_DoIPTpTxConfirmation()</code>.</li>\n</ol>\n<ol class=\"fig-list\">\n<li><strong>Timeouts, Abbruch und Exception Handling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_MainFunction()</code> überwacht Inactivity- und Alive-Check-Timer. Bei Timeout wird <code>SoAd_CloseSoCon()</code> aufgerufen, um die Verbindung zu trennen.</li>\n<li>Bricht der PduR einen Transfer ab (<code>DoIP_TpCancelTransmit()</code> / <code>DoIP_TpCancelReceive()</code> bzw. <code>DoIP_IfCancelTransmit()</code>), schließt <code>DoIP</code> die Transaktion ab.</li>\n<li>Ungültige Header oder API-Fehler führen zum synchronen Aufruf von <code>Det_ReportError()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Routing- und ComStack-Konfiguration:</strong></li>\n<li>Im Konfigurator (<code>ARXML</code>) müssen IF-PDUs (<code>SoAd_IfTransmit</code>, <code>DoIP_IfTransmit</code>, <code>DoIP_SoAdIfRxIndication</code>, <code>DoIP_SoAdIfTxConfirmation</code>, <code>PduR_DoIPIfTxConfirmation</code>) und TP-PDUs (<code>SoAd_TpTransmit</code>, <code>DoIP_TpTransmit</code>, <code>DoIP_SoAdTp<em></code>, <code>PduR_DoIPTp</em></code>) strikt getrennt konfiguriert werden.</li>\n<li>Die Schnittstellen sind als <code>«derived_generic_interface»</code> typisiert; symbolische Namen und PDU-IDs müssen zwischen <code>DoIP</code>, <code>SoAd</code> und <code>PduR</code> exakt übereinstimmen.</li>\n<li><strong>Socket- und IP-Verwaltung:</strong></li>\n<li>Der Verbindungslebenszyklus wird direkt über die dedizierten SoAd-Primitiven <code>SoAd_OpenSoCon()</code>, <code>SoAd_CloseSoCon()</code> und <code>SoAd_GetSoConId()</code> verwaltet; Adresskonflikte oder dynamische IP-Zuweisungen bedingen das Zusammenspiel mit <code>SoAd_RequestIpAddrAssignment()</code> und <code>SoAd_ReleaseIpAddrAssignment()</code>.</li>\n<li><strong>Reentrancy- und Concurrency-Restriktionen:</strong></li>\n<li>Die Callbacks <code>DoIP_SoAdTpCopyTxData()</code>, <code>DoIP_SoAdTpCopyRxData()</code>, <code>PduR_DoIPTpCopyTxData()</code> und <code>PduR_DoIPTpCopyRxData()</code> laufen typischerweise im Kontext hochpriorer Netzwerk-Tasks oder Interrupts und erfordern konsequente Pufferabsicherung über SchM-Locks.</li>\n<li><strong>Normative ISO-13400-2 Abhängigkeiten:</strong></li>\n<li><code>Dcm_GetVin()</code> muss unmittelbar nach Stack-Initialisierung synchron verfügbar sein, um die zeitgerechte Aussendung der Vehicle Announcement Messages nach Adressbezug sicherzustellen.</li>\n</ul>"}, {"id": "FIG-4f336ed30ef925b6", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-2.0-Komponentendiagramm / BSW-Schnittstellenarchitektur (<code>AUTOSAR BSW Module Interface Diagram</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation aller statischen Schnittstellenbeziehungen des BSW-Moduls <code>DoIP</code> (Diagnostic over IP, AUTOSAR Classic R23-11, SWS Chapter 5) zu Nachbarmodulen des Communication- und Diagnostic-Stacks sowie zum BSW-Scheduler und applikativen Callouts.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li><strong>Nach oben (Diagnose-Routing- und Applikationsebene):</strong> Anbindung an den PDU Router (<code>PduR</code>) über transport- und interfacerelevante ComStack-Schnittstellen sowie an den Diagnostic Communication Manager (<code>Dcm</code>) zur VIN-Abfrage.</li>\n<li><strong>Nach unten (Ethernet-Transportebene):</strong> Anbindung an den Socket Adaptor (<code>SoAd</code>) über Communication Interface (IF für UDP) und Transport Protocol (TP für TCP) sowie spezifische Socket- und IP-Adressverwaltungs-APIs.</li>\n<li><strong>System- und Querschnittsfunktionen:</strong> Systemsteuerungs-Hooks (<code>BswM</code>/<code>EcuM</code> via Activation Line und Vehicle Announcement Trigger), Diagnosefehler-Tracing (<code>Det</code>) sowie herstellerspezifische Konfigurations-Callouts (<code>&lt;User&gt;_*</code>) gemäß ISO 13400-2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale Entität</p>\n<ul class=\"fig-list\">\n<li><code>«module» DoIP</code>: Ausführendes BSW-Kernmodul des AUTOSAR Classic Communication Stacks.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen und Modellierungssemantik</p>\n<ul class=\"fig-list\">\n<li><code>«realize»</code>: Vom <code>DoIP</code>-Modul implementierte und exportierte Funktionen/Schnittstellen (Provided Interfaces, linke Modulseite).</li>\n<li><code>«mandatory»</code>: Vom <code>DoIP</code>-Modul zwingend benötigte Aufrufschnittstellen externer BSW-Module (Required Interfaces, rechte Modulseite).</li>\n<li><code>«optional»</code>: Konfigurierbare bzw. bedingt kompilierte Abhängigkeiten (<code>Det_ReportError</code>, <code>PduR_DoIPIfTxConfirmation</code>).</li>\n<li><code>«configurable»</code>: Projektspezifische Anwender-Callbacks (Callouts), die durch OEM-/Integratorcode bereitgestellt werden.</li>\n<li><code>«derived_generic_interface»</code>: Konkret abgeleitete Instanzen standardisierter AUTOSAR ComStack-Primitiven (IF/TP) mit modulspezifischem Namenspräfix für Sender und Empfänger.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenübersicht nach Kommunikationspartnern</p>\n<ol class=\"fig-list\">\n<li><strong>Modul- und Scheduler-Verwaltung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Types</code>: Exportierte Datentypdefinitionen.</li>\n<li><code>DoIP_Init</code>: Modulinitialisierung durch <code>EcuM</code> / <code>BswM</code>.</li>\n<li><code>DoIP_GetVersionInfo</code>: Auslesen der Versionsinformationen.</li>\n<li><code>DoIP_MainFunction</code>: Zyklische BSW-Scheduler-Task für Protokoll-Timer, Session-Monitoring und State-Machine-Updates.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Trigger & Hardware-Aktivierung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_ActivationLineSwitch</code>: Hardware-Flankensignal zur Aktivierung/Deaktivierung des DoIP-Stacks (ISO 13400-2 Activation Line).</li>\n<li><code>DoIP_TriggerVehicleAnnouncement</code>: Manueller/systemischer Trigger zur Aussendung von Vehicle Announcement PDUs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum Socket Adaptor (<code>SoAd</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Required (<code>«mandatory»</code> DoIP $\\rightarrow$ SoAd):</strong></li>\n<li><code>SoAd_GetSoConId</code>: Ermittlung des Socket-Connection-Bezeichners.</li>\n<li><code>SoAd_OpenSoCon</code> / <code>SoAd_CloseSoCon</code>: Explizites Öffnen und Schließen einer Socket-Verbindung.</li>\n<li><code>SoAd_GetPhysAddr</code>: Abfrage der physikalischen MAC-Adresse für eine Socket-Verbindung.</li>\n<li><code>SoAd_RequestIpAddrAssignment</code> / <code>SoAd_ReleaseIpAddrAssignment</code>: Anforderung und Freigabe lokaler IP-Adresszuweisungen.</li>\n<li><code>SoAd_ReadDhcpHostNameOption</code> / <code>SoAd_WriteDhcpHostNameOption</code>: Handhabung der DHCP-Option 12 (Host Name).</li>\n<li><code>«derived_generic_interface» SoAd_IfTransmit</code>: Senden unbestätigter bzw. UDP-basierter DoIP-Nachrichten.</li>\n<li><code>«derived_generic_interface» SoAd_TpTransmit</code>: Initiierung segmentierter TCP-Übertragungen via SoAd-TP.</li>\n<li><strong>Provided / Callbacks (<code>«realize»</code> SoAd $\\rightarrow$ DoIP):</strong></li>\n<li><code>DoIP_SoConModeChg</code>: Benachrichtigung über Zustandswechsel einer Socket-Connection.</li>\n<li><code>DoIP_LocalIpAddrAssignmentChg</code>: Benachrichtigung über Bezug oder Verlust einer lokalen IP-Adresse.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdIfTxConfirmation</code> / <code>DoIP_SoAdIfRxIndication</code>: Statusmeldungen für UDP-basierte Kommunikation.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpStartOfReception</code>, <code>DoIP_SoAdTpCopyRxData</code>, <code>DoIP_SoAdTpRxIndication</code>: Empfangspfad für TCP-basierte DoIP-Nutzlasten via SoAd-TP.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpCopyTxData</code>, <code>DoIP_SoAdTpTxConfirmation</code>: Sendepfad für TCP-basierte DoIP-Antworten via SoAd-TP.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum PDU Router (<code>PduR</code>) & Diagnostic Communication Manager (<code>Dcm</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Provided für PduR (<code>«realize»</code> PduR $\\rightarrow$ DoIP):</strong></li>\n<li><code>«derived_generic_interface» DoIP_TpTransmit</code>: Anforderung des PduR zur Übertragung diagnostischer Transportnachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfTransmit</code>: Anforderung des PduR zur Übertragung unbestätigter Diagnosenachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfCancelTransmit</code>: Abbruch einer laufenden IF-Übertragung.</li>\n<li><code>DoIP_TpCancelTransmit</code> / <code>DoIP_TpCancelReceive</code>: Abbruch laufender TP-Sende- bzw. Empfangsvorgänge.</li>\n<li><strong>Required von PduR / Dcm (<code>«mandatory»</code> / <code>«optional»</code> DoIP $\\rightarrow$ PduR/Dcm):</strong></li>\n<li><code>Dcm_GetVin</code> (<code>«mandatory»</code>): Synchrones Auslesen der Fahrzeug-Identifikationsnummer (VIN).</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpStartOfReception</code>, <code>PduR_DoIPTpCopyRxData</code>, <code>PduR_DoIPTpRxIndication</code> (<code>«mandatory»</code>): Weiterleitung empfangener diagnostischer TP-Nutzdaten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpCopyTxData</code>, <code>PduR_DoIPTpTxConfirmation</code> (<code>«mandatory»</code>): Datenabruf und Bestätigung ausgehender TP-Diagnosenachrichten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPIfTxConfirmation</code> (<code>«optional»</code>): Optionale Sende-Bestätigung für IF-Nachrichten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung (Required / <code>«optional»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError</code>: Weiterleitung von Fehlern an den Development Error Tracer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Herstellerspezifische Anwender-Callouts (<code>«configurable»</code> DoIP $\\rightarrow$ User):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>&lt;User&gt;_DoIPGetGidCallback</code>: Abruf der Group Identification (GID) für Fahrzeugflotten-Identifikation.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationAuthentication</code>: OEM-spezifische Authentifizierung vor Aktivierung eines Routing-Kanals.</li>\n<li><code>&lt;User&gt;_DoIPGetPowerModeCallback</code>: Abfrage des Fahrzeug-/ECU-Energiemodus (Diagnosebereitschaft).</li>\n<li><code>&lt;User&gt;_DoIPTriggerGidSyncCallback</code>: Trigger zur GID-Synchronisation bei Multi-ECU-Architekturen.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationConfirmation</code>: Bestätigungsroutine für die Routing-Aktivierung.</li>\n<li><code>&lt;User&gt;_DoIPGetFurtherActionByteCallback</code>: Dynamische Bereitstellung des OEM-spezifischen Statusbytes im Routing-Activation-Response.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stack-Hochlauf und Discovery-Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Init()</code> wird durch <code>EcuM</code>/<code>BswM</code> synchron aufgerufen.</li>\n<li>Das Aktivierungssignal trifft ein (<code>DoIP_ActivationLineSwitch()</code>), gefolgt von der Adressanforderung (<code>SoAd_RequestIpAddrAssignment()</code>) und Rückmeldung über Adressbezug via <code>DoIP_LocalIpAddrAssignmentChg()</code>.</li>\n<li>Das Modul ruft synchron <code>Dcm_GetVin()</code> und <code>&lt;User&gt;_DoIPGetGidCallback()</code> ab.</li>\n<li>Nach Ablauf des Initial Inactivity Timers sendet <code>DoIP</code> über <code>SoAd_IfTransmit()</code> bis zu dreimal die UDP-Vehicle-Announcement-Nachricht (bestätigt via <code>DoIP_SoAdIfTxConfirmation()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TCP-Verbindungsaufbau und Routing-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tester öffnet TCP-Port 13400; SoAd signalisiert den Zustandswechsel über <code>DoIP_SoConModeChg()</code>.</li>\n<li>Zur Steuerung und Identifikation der Sockets verwendet DoIP <code>SoAd_GetSoConId()</code>, <code>SoAd_OpenSoCon()</code> und <code>SoAd_CloseSoCon()</code>.</li>\n<li>Tester sendet Routing Activation Request via TCP; SoAd leitet Daten über <code>DoIP_SoAdTpStartOfReception()</code> $\\rightarrow$ <code>DoIP_SoAdTpCopyRxData()</code> $\\rightarrow$ <code>DoIP_SoAdTpRxIndication()</code> an <code>DoIP</code>.</li>\n<li><code>DoIP</code> verarbeitet den Header und ruft synchron die Callouts <code>&lt;User&gt;_DoIPRoutingActivationAuthentication()</code> und <code>&lt;User&gt;_DoIPRoutingActivationConfirmation()</code> auf.</li>\n<li>Bei Erfolg wird der Routing-Kanal geöffnet, und <code>DoIP</code> sendet die Bestätigung via <code>SoAd_TpTransmit()</code> und <code>DoIP_SoAdTpCopyTxData()</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>UDS-Diagnosedatentransfer (Gateway-Mechanismus DoIP $\\leftrightarrow$ PduR):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rx-Pfad (Tester $\\rightarrow$ PduR):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>SoAd meldet eingehende Segmente über <code>DoIP_SoAdTpStartOfReception()</code>, streamt via <code>DoIP_SoAdTpCopyRxData()</code> und schließt per <code>DoIP_SoAdTpRxIndication()</code> ab.</li>\n<li><code>DoIP</code> decodiert den DoIP-Header, ermittelt die logische Zieladresse und leitet die PDU an den PduR über <code>PduR_DoIPTpStartOfReception()</code> weiter.</li>\n<li>Daten werden per <code>PduR_DoIPTpCopyRxData()</code> direkt an den PduR übergeben und mit <code>PduR_DoIPTpRxIndication()</code> abgeschlossen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Tx-Pfad (PduR $\\rightarrow$ Tester):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR initiiert Antwort über <code>DoIP_TpTransmit()</code>.</li>\n<li><code>DoIP</code> fordert Übertragung bei SoAd an (<code>SoAd_TpTransmit()</code>).</li>\n<li>SoAd holt Header und Payload über <code>DoIP_SoAdTpCopyTxData()</code> ab; <code>DoIP</code> ruft parallel <code>PduR_DoIPTpCopyTxData()</code> auf, um Diagnosedaten aus dem PduR-Puffer abzurufen.</li>\n<li>Abschluss über <code>DoIP_SoAdTpTxConfirmation()</code> $\\rightarrow$ <code>PduR_DoIPTpTxConfirmation()</code>.</li>\n</ol>\n<ol class=\"fig-list\">\n<li><strong>Timeouts, Abbruch und Exception Handling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_MainFunction()</code> überwacht Inactivity- und Alive-Check-Timer. Bei Timeout wird <code>SoAd_CloseSoCon()</code> aufgerufen, um die Verbindung zu trennen.</li>\n<li>Bricht der PduR einen Transfer ab (<code>DoIP_TpCancelTransmit()</code> / <code>DoIP_TpCancelReceive()</code> bzw. <code>DoIP_IfCancelTransmit()</code>), schließt <code>DoIP</code> die Transaktion ab.</li>\n<li>Ungültige Header oder API-Fehler führen zum synchronen Aufruf von <code>Det_ReportError()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Routing- und ComStack-Konfiguration:</strong></li>\n<li>Im Konfigurator (<code>ARXML</code>) müssen IF-PDUs (<code>SoAd_IfTransmit</code>, <code>DoIP_IfTransmit</code>, <code>DoIP_SoAdIfRxIndication</code>, <code>DoIP_SoAdIfTxConfirmation</code>, <code>PduR_DoIPIfTxConfirmation</code>) und TP-PDUs (<code>SoAd_TpTransmit</code>, <code>DoIP_TpTransmit</code>, <code>DoIP_SoAdTp<em></code>, <code>PduR_DoIPTp</em></code>) strikt getrennt konfiguriert werden.</li>\n<li>Die Schnittstellen sind als <code>«derived_generic_interface»</code> typisiert; symbolische Namen und PDU-IDs müssen zwischen <code>DoIP</code>, <code>SoAd</code> und <code>PduR</code> exakt übereinstimmen.</li>\n<li><strong>Socket- und IP-Verwaltung:</strong></li>\n<li>Der Verbindungslebenszyklus wird direkt über die dedizierten SoAd-Primitiven <code>SoAd_OpenSoCon()</code>, <code>SoAd_CloseSoCon()</code> und <code>SoAd_GetSoConId()</code> verwaltet; Adresskonflikte oder dynamische IP-Zuweisungen bedingen das Zusammenspiel mit <code>SoAd_RequestIpAddrAssignment()</code> und <code>SoAd_ReleaseIpAddrAssignment()</code>.</li>\n<li><strong>Callout-Ausführungszeit (Hard Deadlines):</strong></li>\n<li>Die <code>&lt;User&gt;_*</code>-Schnittstellen (insbesondere Authentifizierung und Bestätigung) müssen strikt non-blocking und bounded-time implementiert sein. Eine Verzögerung blockiert die TCP-Zustandsmaschine und führt zum Ablauf des ISO-13400-Initial-Inactivity-Timers (typisch 2000 ms) auf Testerseite.</li>\n<li><strong>Reentrancy- und Concurrency-Restriktionen:</strong></li>\n<li>Die Callbacks <code>DoIP_SoAdTpCopyTxData()</code>, <code>DoIP_SoAdTpCopyRxData()</code>, <code>PduR_DoIPTpCopyTxData()</code> und <code>PduR_DoIPTpCopyRxData()</code> laufen typischerweise im Kontext hochpriorer Netzwerk-Tasks oder Interrupts und erfordern konsequente Pufferabsicherung über SchM-Locks.</li>\n<li><strong>Normative ISO-13400-2 Abhängigkeiten:</strong></li>\n<li><code>Dcm_GetVin()</code> muss unmittelbar nach Stack-Initialisierung synchron verfügbar sein, um die zeitgerechte Aussendung der Vehicle Announcement Messages nach Adressbezug sicherzustellen.</li>\n</ul>"}, {"id": "FIG-6a342620993c58cd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-2.0-Komponentendiagramm / BSW-Schnittstellenarchitektur (<code>AUTOSAR BSW Module Interface Diagram</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation aller statischen Schnittstellenbeziehungen des BSW-Moduls <code>DoIP</code> (Diagnostic over IP, AUTOSAR Classic R23-11, SWS Chapter 5) zu Nachbarmodulen des Communication- und Diagnostic-Stacks sowie zum BSW-Scheduler und applikativen Callouts.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li><strong>Nach oben (Diagnose-Routing- und Applikationsebene):</strong> Anbindung an den PDU Router (<code>PduR</code>) über transport- und interfacerelevante ComStack-Schnittstellen sowie an den Diagnostic Communication Manager (<code>Dcm</code>) zur VIN-Abfrage.</li>\n<li><strong>Nach unten (Ethernet-Transportebene):</strong> Anbindung an den Socket Adaptor (<code>SoAd</code>) über Communication Interface (IF für UDP) und Transport Protocol (TP für TCP) sowie spezifische Socket- und IP-Adressverwaltungs-APIs.</li>\n<li><strong>System- und Querschnittsfunktionen:</strong> Systemsteuerungs-Hooks (<code>BswM</code>/<code>EcuM</code> via Activation Line und Vehicle Announcement Trigger), Diagnosefehler-Tracing (<code>Det</code>) sowie herstellerspezifische Konfigurations-Callouts (<code>&lt;User&gt;_*</code>) gemäß ISO 13400-2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale Entität</p>\n<ul class=\"fig-list\">\n<li><code>«module» DoIP</code>: Ausführendes BSW-Kernmodul des AUTOSAR Classic Communication Stacks.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen und Modellierungssemantik</p>\n<ul class=\"fig-list\">\n<li><code>«realize»</code>: Vom <code>DoIP</code>-Modul implementierte und exportierte Funktionen/Schnittstellen (Provided Interfaces, linke Modulseite).</li>\n<li><code>«mandatory»</code>: Vom <code>DoIP</code>-Modul zwingend benötigte Aufrufschnittstellen externer BSW-Module (Required Interfaces, rechte Modulseite).</li>\n<li><code>«optional»</code>: Konfigurierbare bzw. bedingt kompilierte Abhängigkeiten (<code>Det_ReportError</code>, <code>PduR_DoIPIfTxConfirmation</code>).</li>\n<li><code>«configurable»</code>: Projektspezifische Anwender-Callbacks (Callouts), die durch OEM-/Integratorcode bereitgestellt werden.</li>\n<li><code>«derived_generic_interface»</code>: Konkret abgeleitete Instanzen standardisierter AUTOSAR ComStack-Primitiven (IF/TP) mit modulspezifischem Namenspräfix für Sender und Empfänger.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenübersicht nach Kommunikationspartnern</p>\n<ol class=\"fig-list\">\n<li><strong>Modul- und Scheduler-Verwaltung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Types</code>: Exportierte Datentypdefinitionen.</li>\n<li><code>DoIP_Init</code>: Modulinitialisierung durch <code>EcuM</code> / <code>BswM</code>.</li>\n<li><code>DoIP_GetVersionInfo</code>: Auslesen der Versionsinformationen.</li>\n<li><code>DoIP_MainFunction</code>: Zyklische BSW-Scheduler-Task für Protokoll-Timer, Session-Monitoring und State-Machine-Updates.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Trigger & Hardware-Aktivierung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_ActivationLineSwitch</code>: Hardware-Flankensignal zur Aktivierung/Deaktivierung des DoIP-Stacks (ISO 13400-2 Activation Line).</li>\n<li><code>DoIP_TriggerVehicleAnnouncement</code>: Manueller/systemischer Trigger zur Aussendung von Vehicle Announcement PDUs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum Socket Adaptor (<code>SoAd</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Required (<code>«mandatory»</code> DoIP $\\rightarrow$ SoAd):</strong></li>\n<li><code>SoAd_GetSoConId</code>: Ermittlung des Socket-Connection-Bezeichners.</li>\n<li><code>SoAd_OpenSoCon</code> / <code>SoAd_CloseSoCon</code>: Explizites Öffnen und Schließen einer Socket-Verbindung.</li>\n<li><code>SoAd_GetPhysAddr</code>: Abfrage der physikalischen MAC-Adresse für eine Socket-Verbindung.</li>\n<li><code>SoAd_RequestIpAddrAssignment</code> / <code>SoAd_ReleaseIpAddrAssignment</code>: Anforderung und Freigabe lokaler IP-Adresszuweisungen.</li>\n<li><code>SoAd_ReadDhcpHostNameOption</code> / <code>SoAd_WriteDhcpHostNameOption</code>: Handhabung der DHCP-Option 12 (Host Name).</li>\n<li><code>«derived_generic_interface» SoAd_IfTransmit</code>: Senden unbestätigter bzw. UDP-basierter DoIP-Nachrichten.</li>\n<li><code>«derived_generic_interface» SoAd_TpTransmit</code>: Initiierung segmentierter TCP-Übertragungen via SoAd-TP.</li>\n<li><strong>Provided / Callbacks (<code>«realize»</code> SoAd $\\rightarrow$ DoIP):</strong></li>\n<li><code>DoIP_SoConModeChg</code>: Benachrichtigung über Zustandswechsel einer Socket-Connection.</li>\n<li><code>DoIP_LocalIpAddrAssignmentChg</code>: Benachrichtigung über Bezug oder Verlust einer lokalen IP-Adresse.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdIfTxConfirmation</code> / <code>DoIP_SoAdIfRxIndication</code>: Statusmeldungen für UDP-basierte Kommunikation.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpStartOfReception</code>, <code>DoIP_SoAdTpCopyRxData</code>, <code>DoIP_SoAdTpRxIndication</code>: Empfangspfad für TCP-basierte DoIP-Nutzlasten via SoAd-TP.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpCopyTxData</code>, <code>DoIP_SoAdTpTxConfirmation</code>: Sendepfad für TCP-basierte DoIP-Antworten via SoAd-TP.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum PDU Router (<code>PduR</code>) & Diagnostic Communication Manager (<code>Dcm</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Provided für PduR (<code>«realize»</code> PduR $\\rightarrow$ DoIP):</strong></li>\n<li><code>«derived_generic_interface» DoIP_TpTransmit</code>: Anforderung des PduR zur Übertragung diagnostischer Transportnachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfTransmit</code>: Anforderung des PduR zur Übertragung unbestätigter Diagnosenachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfCancelTransmit</code>: Abbruch einer laufenden IF-Übertragung.</li>\n<li><code>DoIP_TpCancelTransmit</code> / <code>DoIP_TpCancelReceive</code>: Abbruch laufender TP-Sende- bzw. Empfangsvorgänge.</li>\n<li><strong>Required von PduR / Dcm (<code>«mandatory»</code> / <code>«optional»</code> DoIP $\\rightarrow$ PduR/Dcm):</strong></li>\n<li><code>Dcm_GetVin</code> (<code>«mandatory»</code>): Synchrones Auslesen der Fahrzeug-Identifikationsnummer (VIN).</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpStartOfReception</code>, <code>PduR_DoIPTpCopyRxData</code>, <code>PduR_DoIPTpRxIndication</code> (<code>«mandatory»</code>): Weiterleitung empfangener diagnostischer TP-Nutzdaten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpCopyTxData</code>, <code>PduR_DoIPTpTxConfirmation</code> (<code>«mandatory»</code>): Datenabruf und Bestätigung ausgehender TP-Diagnosenachrichten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPIfTxConfirmation</code> (<code>«optional»</code>): Optionale Sende-Bestätigung für IF-Nachrichten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung (Required / <code>«optional»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError</code>: Weiterleitung von Fehlern an den Development Error Tracer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Herstellerspezifische Anwender-Callouts (<code>«configurable»</code> DoIP $\\rightarrow$ User):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>&lt;User&gt;_DoIPGetGidCallback</code>: Abruf der Group Identification (GID) für Fahrzeugflotten-Identifikation.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationAuthentication</code>: OEM-spezifische Authentifizierung vor Aktivierung eines Routing-Kanals.</li>\n<li><code>&lt;User&gt;_DoIPGetPowerModeCallback</code>: Abfrage des Fahrzeug-/ECU-Energiemodus (Diagnosebereitschaft).</li>\n<li><code>&lt;User&gt;_DoIPTriggerGidSyncCallback</code>: Trigger zur GID-Synchronisation bei Multi-ECU-Architekturen.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationConfirmation</code>: Bestätigungsroutine für die Routing-Aktivierung.</li>\n<li><code>&lt;User&gt;_DoIPGetFurtherActionByteCallback</code>: Dynamische Bereitstellung des OEM-spezifischen Statusbytes im Routing-Activation-Response.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stack-Hochlauf und Discovery-Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Init()</code> wird durch <code>EcuM</code>/<code>BswM</code> synchron aufgerufen.</li>\n<li>Das Aktivierungssignal trifft ein (<code>DoIP_ActivationLineSwitch()</code>), gefolgt von der Adressanforderung (<code>SoAd_RequestIpAddrAssignment()</code>) und Rückmeldung über Adressbezug via <code>DoIP_LocalIpAddrAssignmentChg()</code>.</li>\n<li>Das Modul ruft synchron <code>Dcm_GetVin()</code> und <code>&lt;User&gt;_DoIPGetGidCallback()</code> ab.</li>\n<li>Nach Ablauf des Initial Inactivity Timers sendet <code>DoIP</code> über <code>SoAd_IfTransmit()</code> bis zu dreimal die UDP-Vehicle-Announcement-Nachricht (bestätigt via <code>DoIP_SoAdIfTxConfirmation()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TCP-Verbindungsaufbau und Routing-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tester öffnet TCP-Port 13400; SoAd signalisiert den Zustandswechsel über <code>DoIP_SoConModeChg()</code>.</li>\n<li>Zur Steuerung und Identifikation der Sockets verwendet DoIP <code>SoAd_GetSoConId()</code>, <code>SoAd_OpenSoCon()</code> und <code>SoAd_CloseSoCon()</code>.</li>\n<li>Tester sendet Routing Activation Request via TCP; SoAd leitet Daten über <code>DoIP_SoAdTpStartOfReception()</code> $\\rightarrow$ <code>DoIP_SoAdTpCopyRxData()</code> $\\rightarrow$ <code>DoIP_SoAdTpRxIndication()</code> an <code>DoIP</code>.</li>\n<li><code>DoIP</code> verarbeitet den Header und ruft synchron die Callouts <code>&lt;User&gt;_DoIPRoutingActivationAuthentication()</code> und <code>&lt;User&gt;_DoIPRoutingActivationConfirmation()</code> auf.</li>\n<li>Bei Erfolg wird der Routing-Kanal geöffnet, und <code>DoIP</code> sendet die Bestätigung via <code>SoAd_TpTransmit()</code> und <code>DoIP_SoAdTpCopyTxData()</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>UDS-Diagnosedatentransfer (Gateway-Mechanismus DoIP $\\leftrightarrow$ PduR):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rx-Pfad (Tester $\\rightarrow$ PduR):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>SoAd meldet eingehende Segmente über <code>DoIP_SoAdTpStartOfReception()</code>, streamt via <code>DoIP_SoAdTpCopyRxData()</code> und schließt per <code>DoIP_SoAdTpRxIndication()</code> ab.</li>\n<li><code>DoIP</code> decodiert den DoIP-Header, ermittelt die logische Zieladresse und leitet die PDU an den PduR über <code>PduR_DoIPTpStartOfReception()</code> weiter.</li>\n<li>Daten werden per <code>PduR_DoIPTpCopyRxData()</code> direkt an den PduR übergeben und mit <code>PduR_DoIPTpRxIndication()</code> abgeschlossen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Tx-Pfad (PduR $\\rightarrow$ Tester):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR initiiert Antwort über <code>DoIP_TpTransmit()</code>.</li>\n<li><code>DoIP</code> fordert Übertragung bei SoAd an (<code>SoAd_TpTransmit()</code>).</li>\n<li>SoAd holt Header und Payload über <code>DoIP_SoAdTpCopyTxData()</code> ab; <code>DoIP</code> ruft parallel <code>PduR_DoIPTpCopyTxData()</code> auf, um Diagnosedaten aus dem PduR-Puffer abzurufen.</li>\n<li>Abschluss über <code>DoIP_SoAdTpTxConfirmation()</code> $\\rightarrow$ <code>PduR_DoIPTpTxConfirmation()</code>.</li>\n</ol>\n<ol class=\"fig-list\">\n<li><strong>Timeouts, Abbruch und Exception Handling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_MainFunction()</code> überwacht Inactivity- und Alive-Check-Timer. Bei Timeout wird <code>SoAd_CloseSoCon()</code> aufgerufen, um die Verbindung zu trennen.</li>\n<li>Bricht der PduR einen Transfer ab (<code>DoIP_TpCancelTransmit()</code> / <code>DoIP_TpCancelReceive()</code> bzw. <code>DoIP_IfCancelTransmit()</code>), schließt <code>DoIP</code> die Transaktion ab.</li>\n<li>Ungültige Header oder API-Fehler führen zum synchronen Aufruf von <code>Det_ReportError()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Routing- und ComStack-Konfiguration:</strong></li>\n<li>Im Konfigurator (<code>ARXML</code>) müssen IF-PDUs (<code>SoAd_IfTransmit</code>, <code>DoIP_IfTransmit</code>, <code>DoIP_SoAdIfRxIndication</code>, <code>DoIP_SoAdIfTxConfirmation</code>, <code>PduR_DoIPIfTxConfirmation</code>) und TP-PDUs (<code>SoAd_TpTransmit</code>, <code>DoIP_TpTransmit</code>, <code>DoIP_SoAdTp<em></code>, <code>PduR_DoIPTp</em></code>) strikt getrennt konfiguriert werden.</li>\n<li>Die Schnittstellen sind als <code>«derived_generic_interface»</code> typisiert; symbolische Namen und PDU-IDs müssen zwischen <code>DoIP</code>, <code>SoAd</code> und <code>PduR</code> exakt übereinstimmen.</li>\n<li><strong>Socket- und IP-Verwaltung:</strong></li>\n<li>Der Verbindungslebenszyklus wird direkt über die dedizierten SoAd-Primitiven <code>SoAd_OpenSoCon()</code>, <code>SoAd_CloseSoCon()</code> und <code>SoAd_GetSoConId()</code> verwaltet; Adresskonflikte oder dynamische IP-Zuweisungen bedingen das Zusammenspiel mit <code>SoAd_RequestIpAddrAssignment()</code> und <code>SoAd_ReleaseIpAddrAssignment()</code>.</li>\n<li><strong>Callout-Ausführungszeit (Hard Deadlines):</strong></li>\n<li>Die <code>&lt;User&gt;_*</code>-Schnittstellen (insbesondere Authentifizierung und Bestätigung) müssen strikt non-blocking und bounded-time implementiert sein. Eine Verzögerung blockiert die TCP-Zustandsmaschine und führt zum Ablauf des ISO-13400-Initial-Inactivity-Timers (typisch 2000 ms) auf Testerseite.</li>\n<li><strong>Reentrancy- und Concurrency-Restriktionen:</strong></li>\n<li>Die Callbacks <code>DoIP_SoAdTpCopyTxData()</code>, <code>DoIP_SoAdTpCopyRxData()</code>, <code>PduR_DoIPTpCopyTxData()</code> und <code>PduR_DoIPTpCopyRxData()</code> laufen typischerweise im Kontext hochpriorer Netzwerk-Tasks oder Interrupts und erfordern konsequente Pufferabsicherung über SchM-Locks.</li>\n<li><strong>Normative ISO-13400-2 Abhängigkeiten:</strong></li>\n<li><code>Dcm_GetVin()</code> muss unmittelbar nach Stack-Initialisierung synchron verfügbar sein, um die zeitgerechte Aussendung der Vehicle Announcement Messages nach Adressbezug sicherzustellen.</li>\n</ul>"}, {"id": "FIG-79c15a369f003fc3", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-2.0-Komponentendiagramm / BSW-Schnittstellenarchitektur (<code>AUTOSAR BSW Module Interface Diagram</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation aller statischen Schnittstellenbeziehungen des BSW-Moduls <code>DoIP</code> (Diagnostic over IP, AUTOSAR Classic R23-11, SWS Chapter 5) zu Nachbarmodulen des Communication- und Diagnostic-Stacks sowie zum BSW-Scheduler und applikativen Callouts.</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li><strong>Nach oben (Diagnose-Routing- und Applikationsebene):</strong> Anbindung an den PDU Router (<code>PduR</code>) über transport- und interfacerelevante ComStack-Schnittstellen sowie an den Diagnostic Communication Manager (<code>Dcm</code>) zur VIN-Abfrage.</li>\n<li><strong>Nach unten (Ethernet-Transportebene):</strong> Anbindung an den Socket Adaptor (<code>SoAd</code>) über Communication Interface (IF für UDP) und Transport Protocol (TP für TCP) sowie spezifische Socket- und IP-Adressverwaltungs-APIs.</li>\n<li><strong>System- und Querschnittsfunktionen:</strong> Systemsteuerungs-Hooks (<code>BswM</code>/<code>EcuM</code> via Activation Line und Vehicle Announcement Trigger), Diagnosefehler-Tracing (<code>Det</code>) sowie herstellerspezifische Konfigurations-Callouts (<code>&lt;User&gt;_*</code>) gemäß ISO 13400-2.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Zentrale Entität</p>\n<ul class=\"fig-list\">\n<li><code>«module» DoIP</code>: Ausführendes BSW-Kernmodul des AUTOSAR Classic Communication Stacks.</li>\n</ul>\n<p class=\"fig-p\">#### Stereotypen und Modellierungssemantik</p>\n<ul class=\"fig-list\">\n<li><code>«realize»</code>: Vom <code>DoIP</code>-Modul implementierte und exportierte Funktionen/Schnittstellen (Provided Interfaces, linke Modulseite).</li>\n<li><code>«mandatory»</code>: Vom <code>DoIP</code>-Modul zwingend benötigte Aufrufschnittstellen externer BSW-Module (Required Interfaces, rechte Modulseite).</li>\n<li><code>«optional»</code>: Konfigurierbare bzw. bedingt kompilierte Abhängigkeiten (<code>Det_ReportError</code>, <code>PduR_DoIPIfTxConfirmation</code>).</li>\n<li><code>«configurable»</code>: Projektspezifische Anwender-Callbacks (Callouts), die durch OEM-/Integratorcode bereitgestellt werden.</li>\n<li><code>«derived_generic_interface»</code>: Konkret abgeleitete Instanzen standardisierter AUTOSAR ComStack-Primitiven (IF/TP/SoConModeChg) mit modulspezifischem Namenspräfix für Sender und Empfänger.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenübersicht nach Kommunikationspartnern</p>\n<ol class=\"fig-list\">\n<li><strong>Modul- und Scheduler-Verwaltung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Types</code>: Exportierte Datentypdefinitionen.</li>\n<li><code>DoIP_Init</code>: Modulinitialisierung durch <code>EcuM</code> / <code>BswM</code>.</li>\n<li><code>DoIP_GetVersionInfo</code>: Auslesen der Versionsinformationen.</li>\n<li><code>DoIP_MainFunction</code>: Zyklische BSW-Scheduler-Task für Protokoll-Timer, Session-Monitoring und State-Machine-Updates.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Trigger & Hardware-Aktivierung (Provided / <code>«realize»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_ActivationLineSwitch</code>: Hardware-Flankensignal zur Aktivierung/Deaktivierung des DoIP-Stacks (ISO 13400-2 Activation Line).</li>\n<li><code>DoIP_TriggerVehicleAnnouncement</code>: Manueller/systemischer Trigger zur Aussendung von Vehicle Announcement PDUs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum Socket Adaptor (<code>SoAd</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Required (<code>«mandatory»</code> DoIP $\\rightarrow$ SoAd):</strong></li>\n<li><code>SoAd_GetSoConId</code>: Ermittlung des Socket-Connection-Bezeichners.</li>\n<li><code>SoAd_OpenSoCon</code> / <code>SoAd_CloseSoCon</code>: Explizites Öffnen und Schließen einer Socket-Verbindung.</li>\n<li><code>SoAd_GetPhysAddr</code>: Abfrage der physikalischen MAC-Adresse für eine Socket-Verbindung.</li>\n<li><code>SoAd_RequestIpAddrAssignment</code> / <code>SoAd_ReleaseIpAddrAssignment</code>: Anforderung und Freigabe lokaler IP-Adresszuweisungen.</li>\n<li><code>SoAd_ReadDhcpHostNameOption</code> / <code>SoAd_WriteDhcpHostNameOption</code>: Handhabung der DHCP-Option 12 (Host Name).</li>\n<li><code>«derived_generic_interface» SoAd_IfTransmit</code>: Senden unbestätigter bzw. UDP-basierter DoIP-Nachrichten.</li>\n<li><code>«derived_generic_interface» SoAd_TpTransmit</code>: Initiierung segmentierter TCP-Übertragungen via SoAd-TP.</li>\n<li><strong>Provided / Callbacks (<code>«realize»</code> SoAd $\\rightarrow$ DoIP):</strong></li>\n<li><code>«derived_generic_interface» DoIP_SoConModeChg</code>: Benachrichtigung über Zustandswechsel einer Socket-Connection.</li>\n<li><code>DoIP_LocalIpAddrAssignmentChg</code>: Benachrichtigung über Bezug oder Verlust einer lokalen IP-Adresse.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdIfTxConfirmation</code> / <code>DoIP_SoAdIfRxIndication</code>: Statusmeldungen für UDP-basierte Kommunikation.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpStartOfReception</code>, <code>DoIP_SoAdTpCopyRxData</code>, <code>DoIP_SoAdTpRxIndication</code>: Empfangspfad für TCP-basierte DoIP-Nutzlasten via SoAd-TP.</li>\n<li><code>«derived_generic_interface» DoIP_SoAdTpCopyTxData</code>, <code>DoIP_SoAdTpTxConfirmation</code>: Sendepfad für TCP-basierte DoIP-Antworten via SoAd-TP.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Schnittstellen zum PDU Router (<code>PduR</code>) & Diagnostic Communication Manager (<code>Dcm</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Provided für PduR (<code>«realize»</code> PduR $\\rightarrow$ DoIP):</strong></li>\n<li><code>«derived_generic_interface» DoIP_TpTransmit</code>: Anforderung des PduR zur Übertragung diagnostischer Transportnachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfTransmit</code>: Anforderung des PduR zur Übertragung unbestätigter Diagnosenachrichten.</li>\n<li><code>«derived_generic_interface» DoIP_IfCancelTransmit</code>: Abbruch einer laufenden IF-Übertragung.</li>\n<li><code>DoIP_TpCancelTransmit</code> / <code>DoIP_TpCancelReceive</code>: Abbruch laufender TP-Sende- bzw. Empfangsvorgänge.</li>\n<li><strong>Required von PduR / Dcm (<code>«mandatory»</code> / <code>«optional»</code> DoIP $\\rightarrow$ PduR/Dcm):</strong></li>\n<li><code>Dcm_GetVin</code> (<code>«mandatory»</code>): Synchrones Auslesen der Fahrzeug-Identifikationsnummer (VIN).</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpStartOfReception</code>, <code>PduR_DoIPTpCopyRxData</code>, <code>PduR_DoIPTpRxIndication</code> (<code>«mandatory»</code>): Weiterleitung empfangener diagnostischer TP-Nutzdaten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPTpCopyTxData</code>, <code>PduR_DoIPTpTxConfirmation</code> (<code>«mandatory»</code>): Datenabruf und Bestätigung ausgehender TP-Diagnosenachrichten an den PduR.</li>\n<li><code>«derived_generic_interface» PduR_DoIPIfTxConfirmation</code> (<code>«optional»</code>): Optionale Sende-Bestätigung für IF-Nachrichten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerbehandlung (Required / <code>«optional»</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Det_ReportError</code>: Weiterleitung von Fehlern an den Development Error Tracer.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Herstellerspezifische Anwender-Callouts (<code>«configurable»</code> DoIP $\\rightarrow$ User):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>&lt;User&gt;_DoIPGetGidCallback</code>: Abruf der Group Identification (GID) für Fahrzeugflotten-Identifikation.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationAuthentication</code>: OEM-spezifische Authentifizierung vor Aktivierung eines Routing-Kanals.</li>\n<li><code>&lt;User&gt;_DoIPGetPowerModeCallback</code>: Abfrage des Fahrzeug-/ECU-Energiemodus (Diagnosebereitschaft).</li>\n<li><code>&lt;User&gt;_DoIPTriggerGidSyncCallback</code>: Trigger zur GID-Synchronisation bei Multi-ECU-Architekturen.</li>\n<li><code>&lt;User&gt;_DoIPRoutingActivationConfirmation</code>: Bestätigungsroutine für die Routing-Aktivierung.</li>\n<li><code>&lt;User&gt;_DoIPGetFurtherActionByteCallback</code>: Dynamische Bereitstellung des OEM-spezifischen Statusbytes im Routing-Activation-Response.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stack-Hochlauf und Discovery-Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_Init()</code> wird durch <code>EcuM</code>/<code>BswM</code> synchron aufgerufen.</li>\n<li>Das Aktivierungssignal trifft ein (<code>DoIP_ActivationLineSwitch()</code>), gefolgt von der Adressanforderung (<code>SoAd_RequestIpAddrAssignment()</code>) und Rückmeldung über Adressbezug via <code>DoIP_LocalIpAddrAssignmentChg()</code>.</li>\n<li>Das Modul ruft synchron <code>Dcm_GetVin()</code> und <code>&lt;User&gt;_DoIPGetGidCallback()</code> ab.</li>\n<li>Nach Ablauf des Initial Inactivity Timers sendet <code>DoIP</code> über <code>SoAd_IfTransmit()</code> bis zu dreimal die UDP-Vehicle-Announcement-Nachricht (bestätigt via <code>DoIP_SoAdIfTxConfirmation()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>TCP-Verbindungsaufbau und Routing-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tester öffnet TCP-Port 13400; SoAd signalisiert den Zustandswechsel über <code>DoIP_SoConModeChg()</code>.</li>\n<li>Zur Steuerung und Identifikation der Sockets verwendet DoIP <code>SoAd_GetSoConId()</code>, <code>SoAd_OpenSoCon()</code> und <code>SoAd_CloseSoCon()</code>.</li>\n<li>Tester sendet Routing Activation Request via TCP; SoAd leitet Daten über <code>DoIP_SoAdTpStartOfReception()</code> $\\rightarrow$ <code>DoIP_SoAdTpCopyRxData()</code> $\\rightarrow$ <code>DoIP_SoAdTpRxIndication()</code> an <code>DoIP</code>.</li>\n<li><code>DoIP</code> verarbeitet den Header und ruft synchron die Callouts <code>&lt;User&gt;_DoIPRoutingActivationAuthentication()</code> und <code>&lt;User&gt;_DoIPRoutingActivationConfirmation()</code> auf.</li>\n<li>Bei Erfolg wird der Routing-Kanal geöffnet, und <code>DoIP</code> sendet die Bestätigung via <code>SoAd_TpTransmit()</code> und <code>DoIP_SoAdTpCopyTxData()</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>UDS-Diagnosedatentransfer (Gateway-Mechanismus DoIP $\\leftrightarrow$ PduR):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Rx-Pfad (Tester $\\rightarrow$ PduR):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>SoAd meldet eingehende Segmente über <code>DoIP_SoAdTpStartOfReception()</code>, streamt via <code>DoIP_SoAdTpCopyRxData()</code> und schließt per <code>DoIP_SoAdTpRxIndication()</code> ab.</li>\n<li><code>DoIP</code> decodiert den DoIP-Header, ermittelt die logische Zieladresse und leitet die PDU an den PduR über <code>PduR_DoIPTpStartOfReception()</code> weiter.</li>\n<li>Daten werden per <code>PduR_DoIPTpCopyRxData()</code> direkt an den PduR übergeben und mit <code>PduR_DoIPTpRxIndication()</code> abgeschlossen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Tx-Pfad (PduR $\\rightarrow$ Tester):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>PduR initiiert Antwort über <code>DoIP_TpTransmit()</code>.</li>\n<li><code>DoIP</code> fordert Übertragung bei SoAd an (<code>SoAd_TpTransmit()</code>).</li>\n<li>SoAd holt Header und Payload über <code>DoIP_SoAdTpCopyTxData()</code> ab; <code>DoIP</code> ruft parallel <code>PduR_DoIPTpCopyTxData()</code> auf, um Diagnosedaten aus dem PduR-Puffer abzurufen.</li>\n<li>Abschluss über <code>DoIP_SoAdTpTxConfirmation()</code> $\\rightarrow$ <code>PduR_DoIPTpTxConfirmation()</code>.</li>\n</ol>\n<ol class=\"fig-list\">\n<li><strong>Timeouts, Abbruch und Exception Handling:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DoIP_MainFunction()</code> überwacht Inactivity- und Alive-Check-Timer. Bei Timeout wird <code>SoAd_CloseSoCon()</code> aufgerufen, um die Verbindung zu trennen.</li>\n<li>Bricht der PduR einen Transfer ab (<code>DoIP_TpCancelTransmit()</code> / <code>DoIP_TpCancelReceive()</code> bzw. <code>DoIP_IfCancelTransmit()</code>), schließt <code>DoIP</code> die Transaktion ab.</li>\n<li>Ungültige Header oder API-Fehler führen zum synchronen Aufruf von <code>Det_ReportError()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Routing- und ComStack-Konfiguration:</strong></li>\n<li>Im Konfigurator (<code>ARXML</code>) müssen IF-PDUs (<code>SoAd_IfTransmit</code>, <code>DoIP_IfTransmit</code>, <code>DoIP_SoAdIfRxIndication</code>, <code>DoIP_SoAdIfTxConfirmation</code>, <code>PduR_DoIPIfTxConfirmation</code>) und TP-PDUs (<code>SoAd_TpTransmit</code>, <code>DoIP_TpTransmit</code>, <code>DoIP_SoAdTp<em></code>, <code>PduR_DoIPTp</em></code>) strikt getrennt konfiguriert werden.</li>\n<li>Die Schnittstellen sind als <code>«derived_generic_interface»</code> typisiert; symbolische Namen und PDU-IDs müssen zwischen <code>DoIP</code>, <code>SoAd</code> und <code>PduR</code> exakt übereinstimmen.</li>\n<li><strong>Socket- und IP-Verwaltung:</strong></li>\n<li>Der Verbindungslebenszyklus wird direkt über die dedizierten SoAd-Primitiven <code>SoAd_OpenSoCon()</code>, <code>SoAd_CloseSoCon()</code> und <code>SoAd_GetSoConId()</code> verwaltet; Adresskonflikte oder dynamische IP-Zuweisungen bedingen das Zusammenspiel mit <code>SoAd_RequestIpAddrAssignment()</code> und <code>SoAd_ReleaseIpAddrAssignment()</code>.</li>\n<li><strong>Callout-Ausführungszeit (Hard Deadlines):</strong></li>\n<li>Die <code>&lt;User&gt;_*</code>-Schnittstellen (insbesondere Authentifizierung und Bestätigung) müssen strikt non-blocking und bounded-time implementiert sein. Eine Verzögerung blockiert die TCP-Zustandsmaschine und führt zum Ablauf des ISO-13400-Initial-Inactivity-Timers (typisch 2000 ms) auf Testerseite.</li>\n<li><strong>Reentrancy- und Concurrency-Restriktionen:</strong></li>\n<li>Die Callbacks <code>DoIP_SoAdTpCopyTxData()</code>, <code>DoIP_SoAdTpCopyRxData()</code>, <code>PduR_DoIPTpCopyTxData()</code> und <code>PduR_DoIPTpCopyRxData()</code> laufen typischerweise im Kontext hochpriorer Netzwerk-Tasks oder Interrupts und erfordern konsequente Pufferabsicherung über SchM-Locks.</li>\n<li><strong>Normative ISO-13400-2 Abhängigkeiten:</strong></li>\n<li><code>Dcm_GetVin()</code> muss unmittelbar nach Stack-Initialisierung synchron verfügbar sein, um die zeitgerechte Aussendung der Vehicle Announcement Messages nach Adressbezug sicherzustellen.</li>\n</ul>"}], "trans": [{"from": "FIG-76be091f06177fc6", "to": "FIG-21343f4f1ef8c8c1", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Herstellerspezifische Callouts: Alle sechs <code>&lt;User&gt;_*</code>-Schnittstellen (<code>&lt;User&gt;_DoIPGetPowerModeCallback</code>, <code>&lt;User&gt;_DoIPRoutingActivationConfirmation</code>, <code>&lt;User&gt;_DoIPRoutingActivationAuthentication</code>, <code>&lt;User&gt;_DoIPTriggerGidSyncCallback</code>, <code>&lt;User&gt;_DoIPGetFurtherActionByteCallback</code>, <code>&lt;User&gt;_DoIPGetGidCallback</code>) wurden aus dem Schnittstellendiagramm entfernt.</li>\n<li>ComStack-Schnittstellen: Generische Schnittstellen (<code>«generic_interface»</code>) wurden durch explizit typisierte Schnittstellen (<code>«derived_generic_interface»</code>) mit modulspezifischem Namenspräfix ersetzt; obere Transportschnittstellen wurden von generischen ComStack-/Dcm-Bezeichnern auf konkrete <code>PduR_*</code>-Schnittstellen (<code>PduR_DoIPTpCopyTxData</code>, <code>PduR_DoIPTpCopyRxData</code>, <code>PduR_DoIPTpTxConfirmation</code>, <code>PduR_DoIPTpRxIndication</code>, <code>PduR_DoIPTpStartOfReception</code>, <code>PduR_DoIPIfTxConfirmation</code>) umgestellt.</li>\n<li>SoAd-Schnittstellen: Umfassende Restrukturierung der Socket-Steuerung; <code>SoAd_SoConCtrl</code>, <code>SoAd_Info</code>, <code>SoAd_GeneralCtrl</code>, <code>SoAd_SetRemoteAddr</code> und <code>SoAd_SetUniqueRemoteAddr</code> wurden entfernt und durch <code>SoAd_GetSoConId</code>, <code>SoAd_CloseSoCon</code>, <code>SoAd_OpenSoCon</code>, <code>SoAd_ReleaseIpAddrAssignment</code>, <code>SoAd_RequestIpAddrAssignment</code> sowie <code>SoAd_GetPhysAddr</code> ersetzt.</li>\n<li>Diagrammanordnung: Alle vom DoIP bereitgestellten Schnittstellen (<code>«realize»</code>) sind nun auf der linken Modulseite angeordnet (einschließlich <code>DoIP_TriggerVehicleAnnouncement</code>, <code>DoIP_ActivationLineSwitch</code>, <code>DoIP_LocalIpAddrAssignmentChg</code>, <code>DoIP_TpCancelReceive</code>, <code>DoIP_TpCancelTransmit</code>); alle konsumierten Schnittstellen (<code>«mandatory»</code>, <code>«optional»</code>) befinden sich auf der rechten Modulseite.</li>\n</ul>"}, {"from": "FIG-21343f4f1ef8c8c1", "to": "FIG-4f336ed30ef925b6", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Herstellerspezifische Callouts: Wiedereinführung der sechs anwenderspezifischen Callout-Schnittstellen (<code>«configurable»</code>) auf der rechten Modulseite (<code>&lt;User&gt;_DoIPGetGidCallback</code>, <code>&lt;User&gt;_DoIPRoutingActivationAuthentication</code>, <code>&lt;User&gt;_DoIPGetPowerModeCallback</code>, <code>&lt;User&gt;_DoIPTriggerGidSyncCallback</code>, <code>&lt;User&gt;_DoIPRoutingActivationConfirmation</code>, <code>&lt;User&gt;_DoIPGetFurtherActionByteCallback</code>).</li>\n</ul>"}, {"from": "FIG-4f336ed30ef925b6", "to": "FIG-6a342620993c58cd", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>PduR_DoIPTpTxConfirmation</code>: Neupositionierung der Stereotyp-Beschriftung <code>«mandatory»</code> an der Abhängigkeitslinie (Layoutanpassung zur Vermeidung von Textüberlappungen).</li>\n</ul>"}, {"from": "FIG-6a342620993c58cd", "to": "FIG-79c15a369f003fc3", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DoIP_SoConModeChg</code>: Ergänzung des Stereotyps <code>«derived_generic_interface»</code> oberhalb der Schnittstellenbezeichnung.</li>\n</ul>"}]};
